}

package com.example.a2hauto;

import android.content.Intent;
import android.net.Uri;
import android.os.Bundle;
import android.widget.ImageButton;
import android.widget.TextView;
import android.widget.Toast;

import androidx.appcompat.app.AppCompatActivity;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.example.a2hauto.adapter.PlansAdapter;
import com.example.a2hauto.api.ApiClient;
import com.example.a2hauto.api.ApiService;
import com.example.a2hauto.auth.AuthSessionManager;
import com.example.a2hauto.model.ApiResponse;
import com.example.a2hauto.model.Plan;
import com.example.a2hauto.model.PaymentRequest;
import com.example.a2hauto.model.PaymentResponse;

import java.util.ArrayList;
import java.util.List;

import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Response;

public class PlansActivity extends AppCompatActivity implements PlansAdapter.OnPlanSelectedListener {

    private RecyclerView rvPlans;
    private PlansAdapter plansAdapter;
    private ApiService apiService;
    private AuthSessionManager authSessionManager;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_plans);

        authSessionManager = new AuthSessionManager(this);
        apiService = ApiClient.getApiService();

        rvPlans = findViewById(R.id.rvPlans);
        ImageButton btnBack = findViewById(R.id.btnBack);

        btnBack.setOnClickListener(v -> finish());

        rvPlans.setLayoutManager(new LinearLayoutManager(this));
        plansAdapter = new PlansAdapter(new ArrayList<>(), this);
        rvPlans.setAdapter(plansAdapter);

        loadPlans();
    }

    private void loadPlans() {
        // Demo plans - trong thực tế này sẽ từ API
        List<Plan> plans = new ArrayList<>();
        plans.add(new Plan("fee-1", "Gói Cơ Bản", 1, 50000, "Đăng tin 3 lần/tháng", false));
        plans.add(new Plan("fee-2", "Gói Tiêu Chuẩn", 3, 45000, "Đăng tin 10 lần/tháng", true));
        plans.add(new Plan("fee-3", "Gói Pro", 6, 40000, "Đăng tin unlimited", false));
        plans.add(new Plan("fee-4", "Gói VIP", 12, 35000, "Đăng tin unlimited + hỗ trợ", false));

        plansAdapter.setPlans(plans);
    }

    @Override
    public void onPlanSelected(Plan plan) {
        // Tính amount dựa trên số tháng
        double amount = plan.getMonths() * plan.getPricePerMonth();

        // Tạo payment request
        PaymentRequest paymentRequest = new PaymentRequest(amount, plan.getFeeId());

        String token = authSessionManager.getAuthToken();
        if (token == null || token.isEmpty()) {
            Toast.makeText(this, "Vui lòng đăng nhập", Toast.LENGTH_SHORT).show();
            return;
        }

        // Call API để tạo payment
        createPayment(token, paymentRequest);
    }

    private void createPayment(String token, PaymentRequest paymentRequest) {
        apiService.createPayment("Bearer " + token, paymentRequest)
                .enqueue(new Callback<ApiResponse<PaymentResponse>>() {
                    @Override
                    public void onResponse(Call<ApiResponse<PaymentResponse>> call, Response<ApiResponse<PaymentResponse>> response) {
                        if (response.isSuccessful() && response.body() != null) {
                            ApiResponse<PaymentResponse> apiResponse = response.body();
                            if (apiResponse.isSuccess() && apiResponse.getData() != null) {
                                String paymentUrl = apiResponse.getData().getPaymentUrl();
                                if (paymentUrl != null && !paymentUrl.isEmpty()) {
                                    // Redirect đến VNPay
                                    Intent intent = new Intent(Intent.ACTION_VIEW);
                                    intent.setData(Uri.parse(paymentUrl));
                                    startActivity(intent);
                                } else {
                                    Toast.makeText(PlansActivity.this, "Không thể lấy URL thanh toán", Toast.LENGTH_SHORT).show();
                                }
                            } else {
                                Toast.makeText(PlansActivity.this, apiResponse.getMessage(), Toast.LENGTH_SHORT).show();
                            }
                        } else {
                            Toast.makeText(PlansActivity.this, "Lỗi tạo thanh toán", Toast.LENGTH_SHORT).show();
                        }
                    }

                    @Override
                    public void onFailure(Call<ApiResponse<PaymentResponse>> call, Throwable t) {
                        Toast.makeText(PlansActivity.this, "Lỗi: " + t.getMessage(), Toast.LENGTH_SHORT).show();
                    }
                });
    }
}

package com.example.a2hauto;

import android.content.Intent;
import android.net.Uri;
import android.os.Bundle;
import android.widget.ImageButton;
import android.widget.ProgressBar;
import android.widget.TextView;
import android.widget.Toast;

import androidx.appcompat.app.AppCompatActivity;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.example.a2hauto.adapter.PlansAdapter;
import com.example.a2hauto.api.ApiClient;
import com.example.a2hauto.api.ApiService;
import com.example.a2hauto.auth.AuthSessionManager;
import com.example.a2hauto.model.ApiResponse;
import com.example.a2hauto.model.FeeCommission;
import com.example.a2hauto.model.PaymentRequest;
import com.example.a2hauto.model.PaymentResponse;
import com.example.a2hauto.model.Plan;

import java.util.ArrayList;
import java.util.List;

import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Response;

public class PlansActivity extends AppCompatActivity implements PlansAdapter.OnPlanSelectedListener {

    private RecyclerView rvPlans;
    private PlansAdapter plansAdapter;
    private ApiService apiService;
    private AuthSessionManager authSessionManager;
    private ProgressBar progressBar;
    private TextView tvLoading;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_plans);

        authSessionManager = new AuthSessionManager(this);
        apiService = ApiClient.getApiService();

        rvPlans = findViewById(R.id.rvPlans);
        ImageButton btnBack = findViewById(R.id.btnBack);
        progressBar = findViewById(R.id.progressBar);
        tvLoading = findViewById(R.id.tvLoading);

        btnBack.setOnClickListener(v -> finish());

        rvPlans.setLayoutManager(new LinearLayoutManager(this));
        plansAdapter = new PlansAdapter(new ArrayList<>(), this);
        rvPlans.setAdapter(plansAdapter);

        loadPlansFromApi();
    }

    private void loadPlansFromApi() {
        String token = authSessionManager.getAuthToken();
        if (token == null || token.isEmpty()) {
            showError("Vui lòng đăng nhập");
            return;
        }

        progressBar.setVisibility(android.view.View.VISIBLE);
        tvLoading.setVisibility(android.view.View.VISIBLE);

        // Call API để lấy danh sách gói từ database
        apiService.getPackages("Bearer " + token)
                .enqueue(new Callback<com.example.a2hauto.model.FeeCommissionResponse>() {
                    @Override
                    public void onResponse(Call<com.example.a2hauto.model.FeeCommissionResponse> call, 
                                         Response<com.example.a2hauto.model.FeeCommissionResponse> response) {
                        progressBar.setVisibility(android.view.View.GONE);
                        tvLoading.setVisibility(android.view.View.GONE);

                        if (response.isSuccessful() && response.body() != null) {
                            List<FeeCommission> feeCommissions = response.body().getData();
                            if (feeCommissions != null && !feeCommissions.isEmpty()) {
                                List<Plan> plans = convertToPlans(feeCommissions);
                                plansAdapter.setPlans(plans);
                            } else {
                                showError("Không có gói dịch vụ nào");
                            }
                        } else {
                            showError("Không thể tải danh sách gói");
                        }
                    }

                    @Override
                    public void onFailure(Call<com.example.a2hauto.model.FeeCommissionResponse> call, Throwable t) {
                        progressBar.setVisibility(android.view.View.GONE);
                        tvLoading.setVisibility(android.view.View.GONE);
                        showError("Lỗi: " + t.getMessage());
                    }
                });
    }

    private List<Plan> convertToPlans(List<FeeCommission> feeCommissions) {
        List<Plan> plans = new ArrayList<>();
        for (FeeCommission fee : feeCommissions) {
            Plan plan = new Plan(
                    fee.getFeeId(),
                    fee.getFeeName(),
                    fee.getMonthCount(),
                    fee.getPricePerMonth(),
                    fee.getDescription(),
                    fee.isPopular()
            );
            plans.add(plan);
        }
        return plans;
    }

    @Override
    public void onPlanSelected(Plan plan) {
        // Tính amount dựa trên số tháng
        double amount = plan.getMonths() * plan.getPricePerMonth();

        // Tạo payment request
        PaymentRequest paymentRequest = new PaymentRequest(amount, plan.getFeeId());

        String token = authSessionManager.getAuthToken();
        if (token == null || token.isEmpty()) {
            Toast.makeText(this, "Vui lòng đăng nhập", Toast.LENGTH_SHORT).show();
            return;
        }

        // Call API để tạo payment
        createPayment(token, paymentRequest);
    }

    private void createPayment(String token, PaymentRequest paymentRequest) {
        progressBar.setVisibility(android.view.View.VISIBLE);

        apiService.createPayment("Bearer " + token, paymentRequest)
                .enqueue(new Callback<ApiResponse<PaymentResponse>>() {
                    @Override
                    public void onResponse(Call<ApiResponse<PaymentResponse>> call, Response<ApiResponse<PaymentResponse>> response) {
                        progressBar.setVisibility(android.view.View.GONE);

                        if (response.isSuccessful() && response.body() != null) {
                            ApiResponse<PaymentResponse> apiResponse = response.body();
                            if (apiResponse.isSuccess() && apiResponse.getData() != null) {
                                String paymentUrl = apiResponse.getData().getPaymentUrl();
                                if (paymentUrl != null && !paymentUrl.isEmpty()) {
                                    // Redirect đến VNPay
                                    Intent intent = new Intent(Intent.ACTION_VIEW);
                                    intent.setData(Uri.parse(paymentUrl));
                                    startActivity(intent);
                                } else {
                                    Toast.makeText(PlansActivity.this, "Không thể lấy URL thanh toán", Toast.LENGTH_SHORT).show();
                                }
                            } else {
                                Toast.makeText(PlansActivity.this, apiResponse.getMessage(), Toast.LENGTH_SHORT).show();
                            }
                        } else {
                            Toast.makeText(PlansActivity.this, "Lỗi tạo thanh toán", Toast.LENGTH_SHORT).show();
                        }
                    }

                    @Override
                    public void onFailure(Call<ApiResponse<PaymentResponse>> call, Throwable t) {
                        progressBar.setVisibility(android.view.View.GONE);
                        Toast.makeText(PlansActivity.this, "Lỗi: " + t.getMessage(), Toast.LENGTH_SHORT).show();
                    }
                });
    }

    private void showError(String message) {
        Toast.makeText(this, message, Toast.LENGTH_SHORT).show();
    }
}
